 * con una cuenta nueva no se queda fuera del modelo.
 */
function plPorDefecto(code) {
  const c = String(code || "");
  if (c.charAt(0) === "6") {
    const sub = c.slice(0, 2);
    if (sub === "60" || sub === "61") return "4";
    if (sub === "62" || sub === "63") return "7";
    if (sub === "64") return "6";
    if (sub === "66") return "13";
    if (sub === "68") return "8";
    if (sub === "69") return "11";
    return "";
  }
  if (c.charAt(0) === "7") {
    const sub = c.slice(0, 2);
    if (sub === "70") return "1";
    if (sub === "71") return "2";
    if (sub === "73") return "3";
    if (sub === "74" || sub === "75") return "5";
    if (sub === "76") return "12";
    return "";
  }
  return "";
}

